import React, { useEffect, useState } from 'react';
import { api } from './api';
import './App.css';

function App() {
  const [products, setProducts] = useState([]);
  const [formData, setFormData] = useState({ name: '', price: '', category: '', description: '', stock: '' });
  const [editingId, setEditingId] = useState(null);

  useEffect(() => { load(); }, []);

  const load = () => api.getProducts().then(setProducts);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (editingId) {
      await api.updateProduct(editingId, formData);
      setEditingId(null);
    } else {
      await api.createProduct(formData);
    }
    setFormData({ name: '', price: '', category: '', description: '', stock: '' });
    load();
  };

  const startEdit = (p) => {
    setEditingId(p.id);
    setFormData({ name: p.name, price: p.price, category: p.category, description: p.description, stock: p.stock });
    window.scrollTo(0, 0);
  };

  const handleDelete = async (id) => {
    if (window.confirm("Удалить?")) {
      await api.deleteProduct(id);
      load();
    }
  };

  return (
    <div className="store">
      <header>
        <h1>Nail Professional Store</h1>
        <p>Управление ассортиментом</p>
      </header>

      <form className="product-form" onSubmit={handleSubmit}>
        <h2>{editingId ? "Редактировать товар" : "Добавить новый товар"}</h2>
        <input placeholder="Название" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required />
        <input placeholder="Категория" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})} required />
        <input placeholder="Цена" type="number" value={formData.price} onChange={e => setFormData({...formData, price: e.target.value})} required />
        <input placeholder="Количество" type="number" value={formData.stock} onChange={e => setFormData({...formData, stock: e.target.value})} required />
        <textarea placeholder="Описание" value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
        <button type="submit" className="buy-btn">{editingId ? "Сохранить изменения" : "Создать товар"}</button>
        {editingId && <button onClick={() => {setEditingId(null); setFormData({name:'', price:'', category:'', description:'', stock:''})}}>Отмена</button>}
      </form>

      <div className="grid">
        {products.map(p => (
          <div key={p.id} className="card">
            <div className="category-tag">{p.category}</div>
            <h3>{p.name}</h3>
            <p className="desc">{p.description}</p>
            <div className="bottom-info">
              <span className="price">{p.price} ₽</span>
              <span className="stock-count">Склад: {p.stock}</span>
            </div>
            <div className="actions">
              <button onClick={() => startEdit(p)} className="edit-btn">⚙️</button>
              <button onClick={() => handleDelete(p.id)} className="del-btn">🗑️</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default App;
